# Navigation-bar title: logo, then the tool's name
lab_title <- function(tool) {
  htmltools::tagList(htmltools::HTML(lab_logo_svg),
                     htmltools::span(paste0(" \u00b7 ", tool), style = "margin-left:.1rem;"))
}
